WITH flattened AS (SELECT id, service, log_ts, status_code, key, value FROM app_logs LATERAL VIEW EXPLODE(context) li AS key, value) SELECT *, LAG(status_code) OVER (PARTITION BY key ORDER BY log_ts ASC, id ASC, key ASC) AS prev_status_code, LEAD(status_code) OVER (PARTITION BY key ORDER BY log_ts ASC, id ASC, key ASC) AS next_status_code, ROW_NUMBER() OVER (PARTITION BY key ORDER BY log_ts ASC, id ASC, key ASC) AS seq_no, NTILE(5) OVER (PARTITION BY key ORDER BY status_code DESC, id ASC, key ASC) AS status_code_bucket FROM flattened WHERE key = 'trace'
